/// Case-sensitive binary search; O(log catalog size), no allocation.
pub fn lookup(name: []const u8) ?*const Entry {
    if (name.len > 18) return null;
    var lo: usize = 0;
    var hi: usize = entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, name, entries[mid].name)) {
            .lt => hi = mid,
            .gt => lo = mid + 1,
            .eq => return &entries[mid],
        }
    }
    return null;
}
test "catalog is sorted, unique and round trips every entry" {
    for (&entries, 0..) |*entry, i| {
        try std.testing.expect(lookup(entry.name).? == entry);
        if (i != 0) try std.testing.expect(std.mem.order(u8, entries[i - 1].name, entry.name) == .lt);
        try std.testing.expect(@as(u5, @bitCast(entry.targets)) != 0);
    }
    try std.testing.expect(lookup("shpe") == null);
    try std.testing.expect(lookup("Shape") == null);
}
